 static final int GREEN=0xff2a5b42,DARK=0xff23342a,MINT=0xfff1f6ee,MUTED=0xff64766b,RED=0xffab453e;
 DatabaseStore store;LinearLayout body,root;ScrollView scroll;TextView status;String lastError="";String page="Обзор",query="",from="",until="";boolean editing=false,restoringDraft=false;JSONObject formOriginal;String formKind="",formInitial;byte[] pendingExport;String pendingMime,pendingName;int pendingCode;
 List<String[]> csv=new ArrayList<>();
 SyncService sync;boolean syncBusy=false,applyingSync=false,syncForeground=false;String syncStatus="Не подключено";final android.os.Handler syncHandler=new android.os.Handler(android.os.Looper.getMainLooper());final java.util.concurrent.ExecutorService syncExecutor=java.util.concurrent.Executors.newSingleThreadExecutor();final Runnable syncTick=new Runnable(){public void run(){syncNow(false);syncHandler.postDelayed(this,60000);}};
 interface Task{void run()throws Exception;}
