  HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(Color.WHITE);String[] pages={"Обзор","Операции","Склад изделий","Товары и цены","Материалы","Синхронизация","База и копии"};for(String p:pages){Button b=new Button(this);b.setText(p);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(GREEN);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(v->leave(()->navigate(p)));nav.addView(b);}hs.addView(nav);root.addView(hs);
  scroll=new ScrollView(this);scroll.setBackgroundColor(MINT);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(16),dp(16),dp(16),dp(32));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  if(android.os.Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets x=insets.getInsets(WindowInsets.Type.systemBars());root.setPadding(x.left,x.top,x.right,x.bottom);return insets;});
